/**
 * verify-19 — 取消审批迟到回调 (cancel-approval late-arrival callback).
 *
 * The interactive-approvals round-trip in headless-stream.js blocks a
 * CONFIRM-tier tool on an `approval_request` and settles it with the matching
 * verdict for that id (see `interactiveConfirm` / `settleApproval`). Once a
 * request is settled or cancelled its id is removed from `pendingApprovals`, so
 * a *late* accept verdict that arrives afterwards must be a no-op: it must not
 * authorize the current request or any subsequent one. Conversely a normal
 * accept binds strictly to the one request it names.
 *
 * These are independent behavioral controls at the same boundary the verdict
 * pump uses (settleApproval / pendingApprovals), so a different guard (e.g. a
 * binding check or a fresh-request reopen) cannot be the thing rejecting the
 * late verdict here.
 */
import { describe, it, expect } from "vitest";
import { runAgentHeadlessStream } from "../../src/runtime/headless-stream.js";
import { approvalBindingDigest } from "../../src/lib/agent-authority.js";
import { approvalPermissionForContext } from "../../src/lib/approval-grant-ledger.js";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const CONTEXT = {
  tool: "run_shell",
  command: "npm run test:unit",
  riskLevel: "medium",
  reason: "settings rule asks",
};

const REQUIRED_PERMISSION = approvalPermissionForContext(CONTEXT, {
  cwd: process.cwd(),
});

function bindingFor(id) {
  return approvalBindingDigest({
    toolCallId: id,
    args: { command: CONTEXT.command },
    policyDigest: CONTEXT.riskLevel,
  });
}

/** Reuse the existing suite's harness shape: duplex pipe of JSON events. */
function harness({ agentLoop, inputGen, options = {}, deps: depsOverrides = {} }) {
  const lines = [];
  const deps = {
    bootstrap: async () => ({ db: null }),
    getApprovalGate: async () => null,
    writeOut: (s) => lines.push(s),
    writeErr: () => {},
    agentLoop,
    input: inputGen(),
    ...depsOverrides,
  };
  return {
    run: () =>
      runAgentHeadlessStream(
        { expandFileRefs: false, interactiveApprovals: true, ...options },
        deps,
      ),
    events: () =>
      lines
        .join("")
        .trimEnd()
        .split("\n")
        .map((l) => JSON.parse(l)),
  };
}

describe("cancel-approval late-arrival callback", () => {
  it("positive: a normal accept authorizes exactly the one blocked request", async () => {
    const h = harness({
      agentLoop: async function* (_messages, opts) {
        const allowed = await opts.permissionConfirm(CONTEXT);
        yield { type: "response-complete", content: allowed ? "executed" : "denied" };
        yield { type: "run-ended", reason: "complete" };
      },
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80);
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          decision: { kind: "acceptOnce" },
          approve: true,
          binding: bindingFor("appr-1"),
        }) + "\n";
      },
    });
    await h.run();
    const reqs = h.events().filter((e) => e.type === "approval_request");
    expect(reqs).toHaveLength(1);
    expect(reqs[0]).toMatchObject({ id: "appr-1", requested_permissions: [REQUIRED_PERMISSION] });
    expect(
      h.events().find((e) => e.type === "approval_resolved"),
    ).toMatchObject({ id: "appr-1", approved: true, via: "user-approve" });
    expect(h.events().find((e) => e.type === "result").result).toBe("executed");
  });

  it("negative (deny): a late accept after cancellation cannot authorize a new request", async () => {
    // First request is cancelled by a user-deny. A stale accept for that same
    // id arrives later; it must not green-light the SECOND request that the
    // loop opens next. Only a fresh accept for the new id resolves it.
    const h = harness({
      agentLoop: async function* (_messages, opts) {
        const first = await opts.permissionConfirm(CONTEXT); // appr-1
        const second = await opts.permissionConfirm(CONTEXT); // appr-2
        yield {
          type: "response-complete",
          content: `${first}:${second}`,
        };
        yield { type: "run-ended", reason: "complete" };
      },
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80);
        // user denies the first request → appr-1 settles false
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          decision: { kind: "decline", reason: "no" },
          approve: false,
        }) + "\n";
        await sleep(80); // let the loop reach the second confirm (appr-2)
        // a LATE accept for the already-cancelled appr-1: must be a no-op
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          decision: { kind: "acceptOnce" },
          approve: true,
          binding: bindingFor("appr-1"),
        }) + "\n";
        await sleep(80);
        // the second request is still blocked; only its own accept resolves it
        yield JSON.stringify({
          type: "approval",
          id: "appr-2",
          decision: { kind: "acceptOnce" },
          approve: true,
          binding: bindingFor("appr-2"),
        }) + "\n";
      },
    });
    await h.run();
    const reqs = h.events().filter((e) => e.type === "approval_request");
    expect(reqs).toHaveLength(2);
    expect(reqs.map((r) => r.id)).toEqual(["appr-1", "appr-2"]);
    const resolved = h.events().filter((e) => e.type === "approval_resolved");
    // exactly the deny for appr-1 and the accept for appr-2 — the late accept
    // for the cancelled appr-1 emits no resolution and authorizes nothing.
    expect(resolved).toHaveLength(2);
    expect(resolved).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ id: "appr-1", approved: false, via: "user-deny" }),
        expect.objectContaining({ id: "appr-2", approved: true, via: "user-approve" }),
      ]),
    );
    // appr-2 only resolved after its own fresh accept (first stayed denied).
    expect(h.events().find((e) => e.type === "result").result).toBe("false:true");
  });

  it("negative (timeout): a late accept after timeout cannot authorize a new request", async () => {
    process.env.CC_APPROVAL_TIMEOUT_MS = "60";
    const h = harness({
      agentLoop: async function* (_messages, opts) {
        const first = await opts.permissionConfirm(CONTEXT); // appr-1
        const second = await opts.permissionConfirm(CONTEXT); // appr-2
        yield { type: "response-complete", content: `${first}:${second}` };
        yield { type: "run-ended", reason: "complete" };
      },
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80);
        // allow the first request to time out (fails closed) rather than deny it
        await sleep(80);
        // a LATE accept for the already-timed-out appr-1: must be a no-op
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          decision: { kind: "acceptOnce" },
          approve: true,
          binding: bindingFor("appr-1"),
        }) + "\n";
        await sleep(80);
        // the second request is still blocked; only its own accept resolves it
        yield JSON.stringify({
          type: "approval",
          id: "appr-2",
          decision: { kind: "acceptOnce" },
          approve: true,
          binding: bindingFor("appr-2"),
        }) + "\n";
      },
    });
    await h.run();
    const reqs = h.events().filter((e) => e.type === "approval_request");
    expect(reqs).toHaveLength(2);
    expect(reqs.map((r) => r.id)).toEqual(["appr-1", "appr-2"]);
    const resolved = h.events().filter((e) => e.type === "approval_resolved");
    expect(resolved).toHaveLength(2);
    expect(resolved).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ id: "appr-1", approved: false, via: "timeout" }),
        expect.objectContaining({ id: "appr-2", approved: true, via: "user-approve" }),
      ]),
    );
    expect(h.events().find((e) => e.type === "result").result).toBe("false:true");
    delete process.env.CC_APPROVAL_TIMEOUT_MS;
  });

  it("negative (id scoping): a normal accept binds only to its own request", async () => {
    // Two requests are open back-to-back. An accept for appr-1 must resolve
    // exactly appr-1; appr-2 remains pending and only its own accept resolves it.
    const h = harness({
      agentLoop: async function* (_messages, opts) {
        const first = await opts.permissionConfirm(CONTEXT); // appr-1
        const second = await opts.permissionConfirm(CONTEXT); // appr-2
        yield { type: "response-complete", content: `${first}:${second}` };
        yield { type: "run-ended", reason: "complete" };
      },
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) + "\n";
        await sleep(80);
        // accept only appr-1
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          decision: { kind: "acceptOnce" },
          approve: true,
          binding: bindingFor("appr-1"),
        }) + "\n";
        await sleep(80);
        // appr-2 is still pending — resolve it with its own accept
        yield JSON.stringify({
          type: "approval",
          id: "appr-2",
          decision: { kind: "acceptOnce" },
          approve: true,
          binding: bindingFor("appr-2"),
        }) + "\n";
      },
    });
    await h.run();
    const reqs = h.events().filter((e) => e.type === "approval_request");
    expect(reqs.map((r) => r.id)).toEqual(["appr-1", "appr-2"]);
    const resolved = h.events().filter((e) => e.type === "approval_resolved");
    expect(resolved.map((r) => [r.id, r.approved])).toEqual([
      ["appr-1", true],
      ["appr-2", true],
    ]);
    // each accept settled only its own named request.
    expect(h.events().find((e) => e.type === "result").result).toBe("true:true");
  });
});

import "./helpers/test-model-egress.js";
/**
 * verify-19 — "Cancel approval, then a late-arriving accept".
 *
 * Regression coverage for the interactive-approval round-trip:
 *   - Once an approval_request has been settled (e.g. cancelled via a deny
 *     verdict), a *later* accept verdict for the same id must be a strict
 *     no-op: it must not authorize a new request, emit a new
 *     approval_resolved, or green-light any blocked tool.
 *   - A normal accept binds only to the original request it was issued for:
 *     an approve verdict carrying a binding that matches a *different* call
 *     is rejected (fail closed) rather than executing anything.
 *
 * This is exercised through the same runAgentHeadlessStream pump that a
 * chat-panel consumer drives: approval_request is emitted on stdout and
 * {\"type\":\"approval\",...} verdicts arrive on stdin.
 */
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { runAgentHeadlessStream } from "../src/runtime/headless-stream.js";
import { approvalBindingDigest } from "../src/lib/agent-authority.js";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

describe("cancel approval, late accept must not authorize", () => {
  beforeEach(() => {
    process.env.CC_APPROVAL_TIMEOUT_MS = "30000";
  });
  afterEach(() => {
    delete process.env.CC_APPROVAL_TIMEOUT_MS;
  });

  // A tool that requires a CONFIRM-tier decision; the injected
  // permissionConfirm is what executeTool calls for a settings/hook `ask`.
  const riskyConfirm = (opts) =>
    opts.permissionConfirm({
      tool: "run_shell",
      command: "npm run test:unit",
      riskLevel: "medium",
      reason: "settings rule asks",
    });

  // Issues one RISKY confirm per turn and reports the verdict in its reply.
  const singleConfirmLoop = async function* (messages, opts) {
    const lastUser = [...messages].reverse().find((m) => m.role === "user");
    if (/RISKY/.test(lastUser.content)) {
      const ok = await riskyConfirm(opts);
      yield {
        type: "response-complete",
        content: ok ? "executed" : "skipped (denied)",
      };
    } else {
      yield { type: "response-complete", content: "plain reply" };
    }
    yield { type: "run-ended", reason: "complete" };
  };

  // Issues TWO distinct RISKY confirms in sequence. Used to prove that a
  // stale accept for a cancelled first request does not auto-grant the
  // second, unrelated request.
  const twoConfirmLoop = async function* (messages, opts) {
    const lastUser = [...messages].reverse().find((m) => m.role === "user");
    if (!/RISKY/.test(lastUser.content)) {
      yield { type: "response-complete", content: "plain reply" };
      yield { type: "run-ended", reason: "complete" };
      return;
    }
    const ok1 = await riskyConfirm(opts);
    yield {
      type: "response-complete",
      content: ok1 ? "executed" : "skipped (denied)",
    };
    const ok2 = await riskyConfirm(opts);
    yield {
      type: "response-complete",
      content: ok2 ? "executed" : "skipped (denied)",
    };
    yield { type: "run-ended", reason: "complete" };
  };

  function harness({ inputGen, agentLoop = singleConfirmLoop }) {
    const lines = [];
    return {
      run: () =>
        runAgentHeadlessStream(
          { expandFileRefs: false, interactiveApprovals: true },
          {
            bootstrap: async () => ({ db: null }),
            getApprovalGate: async () => null,
            writeOut: (s) => lines.push(s),
            writeErr: () => {},
            agentLoop,
            input: inputGen(),
          },
        ),
      events: () =>
        lines
          .join("")
          .trimEnd()
          .split("\n")
          .map((l) => JSON.parse(l)),
    };
  }

  it("normal accept authorizes exactly the request it was issued for", async () => {
    const expectedBinding = approvalBindingDigest({
      toolCallId: "appr-1",
      args: { command: "npm run test:unit" },
      policyDigest: "medium",
    });
    const h = harness({
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) +
          "\n";
        await sleep(80); // let the turn reach the confirm
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          decision: { kind: "acceptOnce" },
          approve: true,
          binding: expectedBinding,
        }) + "\n";
      },
    });
    await h.run();

    const req = h.events().find((e) => e.type === "approval_request");
    expect(req).toMatchObject({ id: "appr-1", binding: expectedBinding });
    // Exactly one request and exactly one resolution for the accept.
    expect(
      h.events().filter((e) => e.type === "approval_request"),
    ).toHaveLength(1);
    const resolved = h
      .events()
      .filter((e) => e.type === "approval_resolved" && e.id === "appr-1");
    expect(resolved).toHaveLength(1);
    expect(resolved[0]).toMatchObject({
      id: "appr-1",
      approved: true,
      via: "user-approve",
    });
    expect(h.events().find((e) => e.type === "result").result).toBe(
      "executed",
    );
  });

  it("late accept after a cancel is a no-op and cannot authorize a new request", async () => {
    const h = harness({
      agentLoop: twoConfirmLoop,
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) +
          "\n";
        await sleep(80); // reach the first confirm (appr-1)
        // Cancel the first request with a deny verdict.
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          approve: false,
        }) + "\n";
        await sleep(80); // appr-1 settles (deny), first turn skipped
        // A late-arriving accept for the *cancelled* id: must be ignored.
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          approve: true,
        }) + "\n";
        await sleep(80); // loop issues the second RISKY confirm (appr-2)
        // The second, distinct request still needs its own fresh verdict.
        yield JSON.stringify({
          type: "approval",
          id: "appr-2",
          approve: false,
        }) + "\n";
      },
    });
    await h.run();

    const requests = h.events().filter((e) => e.type === "approval_request");
    expect(requests.map((r) => r.id)).toEqual(["appr-1", "appr-2"]);
    expect(requests).toHaveLength(2);

    // appr-1: only the deny resolution — the late accept produced nothing.
    const resolved1 = h
      .events()
      .filter((e) => e.type === "approval_resolved" && e.id === "appr-1");
    expect(resolved1).toHaveLength(1);
    expect(resolved1[0]).toMatchObject({
      id: "appr-1",
      approved: false,
      via: "user-deny",
    });

    // appr-2 was NOT auto-granted by the stale accept for appr-1: it needed
    // its own deny verdict to be settled, and it was not authorized.
    const resolved2 = h
      .events()
      .filter((e) => e.type === "approval_resolved" && e.id === "appr-2");
    expect(resolved2).toHaveLength(1);
    expect(resolved2[0]).toMatchObject({
      id: "appr-2",
      approved: false,
      via: "user-deny",
    });

    // No approval_resolved is emitted with approved:true anywhere.
    expect(
      h.events().some((e) => e.type === "approval_resolved" && e.approved),
    ).toBe(false);

    const results = h
      .events()
      .filter((e) => e.type === "result")
      .map((e) => e.result);
    expect(results).toEqual(["skipped (denied)", "skipped (denied)"]);
  });

  it("a normal accept binds only to the original request (cross-call binding mismatch is rejected)", async () => {
    // A binding computed for a *different* tool call than the one the request
    // advertised (same id, different arguments) must be rejected.
    const foreignBinding = approvalBindingDigest({
      toolCallId: "appr-1",
      args: { command: "rm -rf /" },
      policyDigest: "medium",
    });
    const h = harness({
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "do the RISKY thing" }) +
          "\n";
        await sleep(80);
        yield JSON.stringify({
          type: "approval",
          id: "appr-1",
          decision: { kind: "acceptOnce" },
          approve: true,
          binding: foreignBinding,
        }) + "\n";
      },
    });
    await h.run();

    const req = h.events().find((e) => e.type === "approval_request");
    expect(req.binding).toMatch(/^ab_/);
    expect(req.binding).not.toBe(foreignBinding);

    const resolved = h
      .events()
      .filter((e) => e.type === "approval_resolved" && e.id === "appr-1");
    expect(resolved).toHaveLength(1);
    expect(resolved[0]).toMatchObject({
      id: "appr-1",
      approved: false,
      via: "binding-mismatch",
    });
    // The mismatched accept did not execute anything.
    expect(h.events().find((e) => e.type === "result").result).toBe(
      "skipped (denied)",
    );
  });
});

