          type: "approval",
          id: "appr-1",
          decision: { kind: "acceptOnce" },
          approve: true,
          binding: expectedBinding,
        }) + "\n";
      },
    });
    await h.run();
    const req = h.events().find((e) => e.type === "approval_request");
    expect(req.binding).toBe(expectedBinding);
    expect(req.binding).toMatch(/^ab_[0-9a-f]{32}$/);
    expect(
