  it("reuses an exact acceptForTurn grant without opening a second card", async () => {
    const context = {
      tool: "run_shell",
      command: "npm run test:unit",
      riskLevel: "medium",
      reason: "settings rule asks",
    };
    const expectedBinding = approvalBindingDigest({
      toolCallId: "appr-1",
      args: { command: context.command },
