        sessionExists: () => false,
        startSession: () => {},
        readEvents: () => [],
        readVerifiedEvents: () => [],
        appendUserMessage: () => {},
        appendAssistantMessage: () => {},
        appendEvent: () => true,
        appendAuthorityEvent: (_sessionId, type, data) => {
